import{z as A,x as m,o as E,c as p,q as r,j as s,D as l,d as i,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"6 寸掩模","description":"","frontmatter":{"title":"6 寸掩模","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/six-inch-reticle.md","filePath":"litho/six-inch-reticle.md","lastUpdated":1791063341000}'),B={name:"litho/six-inch-reticle.md"};function d(c,a,h,C,D,u){const t=m("Mermaid");return E(),p("div",null,[a[2]||(a[2]=r('<h1 id="_6-寸掩模" tabindex="-1">6 寸掩模 <a class="header-anchor" href="#_6-寸掩模" aria-label="Permalink to &quot;6 寸掩模&quot;">​</a></h1><div class="epigraph"><p>扫描机认的版是 6 英寸见方的那块石英：尺寸是 SEMI 标准，不是某代节点的设计参数。</p><footer>—— 据 SEMI 对光掩模基板外形尺寸的通称，以及 6 寸（152 mm）reticles 的产线惯例</footer></div><p><a href="/litho/ebeam-mask-pec">上一课</a>把写版邻近钉成 PEC。缺口是承载这些图形的基板：夹具、库、 pellicle 框架、扫描机掩模台，都按同一外形来。本课钉 6 寸掩模。多重图形从下一课序的 <a href="/litho/lele-multipattern">LELE</a> 另起，不在这里染色。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PEC 在一块有限的石英上写出铬或吸收体。这块板的边长、厚度、平坦度决定：能写多大的曝光场、掩模台怎么夹、投影放大率怎么约定。产业默认是 6 英寸正方形基板（通称 6&quot; reticle，边长 152 mm 量级），厚度也按 SEMI 相关规范的外形系列走。本课不把某一条款的毫米公差抄成工艺常数，只钉：标准外形是 6 寸方，不是晶圆那种圆片，也不是「按芯片大小裁一块」。</p><p><span class="marginnote">reticle（掩模版）翻译成大白话就是「印图的母版」：扫描机每次把版上缩小的像投到晶圆的一个场里，再 stepping 到下一个场重复。它是方的，因为要被机械夹具固定和传输，不是因为图形是方的。</span></p><p>缺口因此是机械与标准，不是再卷积一次电子核。把场尺寸写成镜头随便取，会漏掉 6 寸有效区减去 pellicle 框架与条码之后剩下的那块；把 EUV 版想成另一种边长，会漏掉 EUV 公开上仍沿用同一外形家族、改的是反射膜系与厚度/夹持细节。</p><h3 id="_6-寸不是光学-na" tabindex="-1">6 寸不是光学 NA <a class="header-anchor" href="#_6-寸不是光学-na" aria-label="Permalink to &quot;6 寸不是光学 NA&quot;">​</a></h3><p>放大率（DUV 透射常见 \\(4\\times\\)）把晶圆场映回版上的面积。6 寸给出版侧最大面积预算；镜头像场再截一刀。两者一起决定 \\(N_\\mathrm{f}\\) 和产能会计里的场数，但 6 寸本身不提高 NA。更大基板（公开讨论过的 9 寸一类）会改写模机、库、扫描台，量产主流没有换成它来「多印一点」。</p><p><span class="marginnote">报掩模规格时声明外形系列与膜系（二元铬、衰减相移、EUV 多层），不要只说「6 寸所以 CDU 更好」。CDU 来自写与刻，不来自边长。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>产线接口：掩模台真空或机械夹持按 6 寸设计；pellicle 框架按 6 寸有效区安装；自动化库的槽位、条码位置按同一外形。换外形等于换整条物流。写模：有效写区小于基板边长，边缘要留夹持与检测。上一课的拼接场次数与这块有效区有关——版更大，单场光学未必更大，写拼接可以更多或更少，取决于写模策略，不要假设 6 寸「自动减少 PPE」。</p><p><span class="marginnote">为什么重要：场规划若按基板边长而不是有效光学区来算，会把场画进 pellicle 框架和夹持边的阴影里——版写完、装上台才发现边缘一圈图形根本曝不到，整个场布局重排。</span></p><p>EUV：反射、无（或有特殊）pellicle、吸收体厚，但公开平台仍按 6 寸家族进掩模台。夹持、热、背面缺陷是 EUV 掩模课，本课只承认外形连续，膜系不连续。</p><h3 id="后课默认" tabindex="-1">后课默认 <a class="header-anchor" href="#后课默认" aria-label="Permalink to &quot;后课默认&quot;">​</a></h3><p>说到 reticle，默认 6 寸方基板、DUV \\(4\\times\\) 透射，除非声明 EUV 反射或特殊放大。说到场尺寸，先查镜头像场与 6 寸有效区谁先截断。</p>',16)),(E(),s(o,null,{default:l(()=>[n(t,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEMI%5B%22SEMI%20%E5%A4%96%E5%BD%A2%3A%206%20%E5%AF%B8%E6%96%B9%22%5D%20--%3E%20STAGE%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E6%8E%A9%E6%A8%A1%E5%8F%B0%22%5D%0A%20%20SEMI%20--%3E%20PEL%5B%22Pellicle%20%E6%A1%86%E6%9E%B6%20%2F%20%E5%BA%93%22%5D%0A%20%20PEC%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20PEC%20%E5%86%99%E5%87%BA%22%5D%20--%3E%20AREA%5B%22%E6%9C%89%E6%95%88%E5%86%99%E5%8C%BA%22%5D%0A%20%20AREA%20--%3E%20FIELD%5B%22%E6%99%B6%E5%9C%86%E5%9C%BA%20%C3%97%20%E6%94%BE%E5%A4%A7%E7%8E%87%22%5D%0A%20%20STAGE%20--%3E%20SCAN%5B%22%E6%9B%9D%E5%85%89%22%5D%0A%20%20FIELD%20--%3E%20SCAN%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[i("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"投影光刻把掩模当作物面。物面必须有标准夹持几何，否则每块版的弯曲、倾斜进套刻与焦面。SEMI 一类标准把边长、厚度、倒角、标识区统一，让掩模厂、扫描机、检验机共用机械接口。光学上，\\(4\\times\\) 意味着晶圆 26 mm 量级的场在版上约 100 mm 量级，6 寸（152 mm）边长刚好留下边框给 pellicle 与条码——这是历史收敛，不是瑞利式推出来的。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"数字实例：\\(4\\times\\) 放大下，晶圆上 26 mm 见方的场，到版上占约 104 mm 见方；152 mm 的基板减去这 104 mm，四周各剩约 24 mm 给夹持边、pellicle 框和条码——可见有效光学区离基板边长还差着好几圈。")],-1)),(E(),s(o,null,{default:l(()=>[n(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%226%20%E5%AF%B8%E5%9F%BA%E6%9D%BF%EF%BC%9A152%20mm%20%E6%96%B9%22%5D%20--%3E%20W%5B%22%E6%9C%89%E6%95%88%E5%86%99%E5%8C%BA%EF%BC%9A%E7%95%99%E5%A4%B9%E6%8C%81%E4%B8%8E%E6%A3%80%E6%B5%8B%E8%BE%B9%E6%A1%86%22%5D%0A%20%20W%20--%3E%20P%5B%22Pellicle%20%E4%B9%8B%E4%B8%8B%E7%9A%84%E6%9C%89%E6%95%88%E5%85%89%E5%AD%A6%E5%8C%BA%22%5D%0A%20%20P%20--%3E%20L%7B%22%E9%95%9C%E5%A4%B4%E5%83%8F%E5%9C%BA%E5%86%8D%E6%88%AA%E4%B8%80%E5%88%80%22%7D%0A%20%20L%20--%3E%20F%5B%22%E7%89%88%E4%B8%8A%E7%89%A9%E5%9C%BA%EF%BC%9A%E7%BA%A6%20104%20mm%20%E6%96%B9%22%5D%0A%20%20F%20--%3E%20WF%5B%22%E6%99%B6%E5%9C%86%E4%B8%8A%2026%20mm%20%E9%87%8F%E7%BA%A7%E7%9A%84%E5%9C%BA%22%5D%0A"})]),fallback:l(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>热：6 寸石英的热容量与夹持导热，进入掩模加热课；外形给定后，功率与吸收才是变量。PEC 与 6 寸正交：散射核不认边长，但靠边的图形缺邻居，长程 PEC 要处理「版外无图形」的边界。</p><p><span class="marginnote">不要把「6 寸」写成 EUV 不能用大场的原因。EUV 场受反射镜头与 anamorphic 设计限制，基板外形是约束之一，不是唯一约束。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不引用未核对的 SEMI 条款号当数字来源，不编 9 寸为何失败的内幕。不把掩模缺陷检验波长写进本课。下一课序 LELE 会一张层用两块 6 寸版，物流与套刻预算加倍，外形仍是同一标准。</p><p>晶圆是 300 mm 圆，掩模是 152 mm 方：不要在示意图里画成一样的圆片。pellicle 面积小于基板，有效光学区再小一圈，场规划必须用有效区。写模 PEC 的长程核在这块有限方板上有边界：版外无图形，边框 CD 与中心密度区不同，外形因此间接进入 mask CDU。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量产 reticle 默认 6 寸正方形基板，外形由 SEMI 一类标准约束。</li><li>边长定夹持、库、pellicle 与有效写区，不定 NA。</li><li>EUV 沿用外形家族，改膜系与夹持，不在本课展开。</li><li>场尺寸由镜头像场与 6 寸有效区共同截断。</li><li>晶圆是圆片、掩模是方板；pellicle 再截一圈有效光学区。</li><li>6 寸不定 CDU；</li><li>出处：SEMI 光掩模基板外形通称；扫描机掩模台对 6 寸版的公开接口惯例。</li></ul>',7))])}const f=A(B,[["render",d]]);export{P as __pageData,f as default};
